'use strict';
const STORE_KEY='pyeongso-operations-v1', BACKUP_SCHEMA='pyeongso-backup-v1';
start='2026-10-01';end='2026-10-12';
pages.dashboard='평소의 현황';pages.menus='메뉴 · 수익성';pages.inventory='식재료 · 저장음식';
let catalogCategory='전체';
const expenseCategories=['임차료','인건비','사업주 부담 보험료','관리비','수도광열비','통신·소프트웨어','광고비','소모품·청소비'];
const categoryNames=['전체','시그니처','소요리','식사 · 마무리','간단 안주','저장음식 활용','주류','논알코올'];
fields.sales.splice(5,0,['quantity_unit','판매 단위','salesUnit']);
fields.sales.find(f=>f[0]==='unit_food_cost_snapshot')[1]='판매 단위당 재료 · 주류 원가 (원)';
fields.sales.find(f=>f[0]==='unit_packaging_cost_snapshot')[1]='판매 단위당 포장원가 (원)';
const oldPeriodUI=periodUI;
periodUI=function(){return oldPeriodUI().replace('실제 기록 기간','조회 기간')};
const oldOpts=opts,oldBind=bind,oldRecordPage=recordPage,oldRecordModal=recordModal,oldValidate=validate;
function icon(kind){let p={chart:'M4 18V12M10 18V7M16 18V3M2 21H22',dish:'M3 12H21M5 12a7 7 0 0 0 14 0M10 4v4M14 3v5',glass:'M6 3H18L16 13H8ZM12 13v8M8 21h8',leaf:'M19 3C8 2 2 8 5 15c4 7 15 4 14-12ZM5 19L15 8',book:'M4 4H10a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4ZM13 7a3 3 0 0 1 3-3h4v15h-3a4 4 0 0 0-4 2'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${p[kind]||p.chart}"/></svg>`}
function intro(title,text,eyebrow='PYEONGSO · OPERATIONS',actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2><p>${text}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`}
function isBeverage(m){return m?.category==='주류'||m?.category==='논알코올'}
function metric(label,value,note,color,shape){return `<div class="overview-card ${color||''}"><div class="overview-label"><span>${label}</span>${icon(shape)}</div><strong class="${value==='—'?'metric-unset':''}">${value}</strong><div class="overview-foot">${note}</div></div>`}
function heading(title,note,link,page){return `<div class="panel-heading"><div><h3>${title}</h3><p>${note}</p></div>${link?`<button class="text-link" data-page="${page}">${link} ↗</button>`:''}</div>`}
function noChart(){return `<div class="trend-empty">${[30,80,130,180].map((top,i)=>`<div class="gridline" style="top:${top}px"><label>${i===3?'0':'—'}</label></div>`).join('')}<div class="empty-chart-message">${icon('chart')}<strong>첫 판매 기록을 기다리고 있어요</strong><span>실제 기록이 쌓이면 매출 흐름을 확인할 수 있습니다.</span></div><div class="date-axis"><span>${start.slice(5).replace('-','.')}</span><span>선택한 조회 기간</span><span>${end.slice(5).replace('-','.')}</span></div></div>`}
function workflow(){return `<div class="workflow"><span>평소의 운영 흐름</span><button data-page="sales">판매 기록 입력</button>→<button data-page="menus">음식 · 주류 수익성</button>→<button data-page="profit">기간 손익</button>→<button data-page="inventory">식재료 · 저장음식 잔량</button></div>`}
dashboard=function(){const s=selected('sales'),e=selected('expenses'),signature=db.menus.filter(m=>m.category==='시그니처'),groups=['음식','주류','논알코올'];const c=monthly();return `${intro('평소의 오늘을 살펴봅니다.','작은 요리와 한 잔의 술, 계절을 담은 운영 기록','SEASONAL SMALL PLATES & DRINKS','<button data-page="inventory">식재료 확인</button><button class="primary" data-add="sales">＋ 판매 기록</button>')}${periodUI()}<div class="overview-cards">${metric('전체 순매출',s.length?won(sum(s,'net_sales')):'—',s.length?'선택 기간 · 실제 기록':'실제 판매 기록 미등록','', 'chart')}${metric('음식 판매',s.length?won(sum(s.filter(r=>!isBeverage(db.menus.find(m=>m.menu_id===r.menu_id))),'net_sales')):'—','소요리 · 플레이트 · 식사 · 간단 안주','yellow','dish')}${metric('주류 판매',s.length?won(sum(s.filter(r=>db.menus.find(m=>m.menu_id===r.menu_id)?.category==='주류'),'net_sales')):'—','맥주 · 하이볼 · 사케 · 소츄','red','glass')}${metric('운영 비용',e.length?won(sum(e,'amount')):'—',e.length?'선택 기간 · 비용 기록':'실제 비용 기록 미등록','','book')}</div><div class="dash-row"><section class="dash-panel">${heading('기간별 매출 흐름','실제 기록만 표시합니다 · 금액 단위: 천 원','판매 내역','sales')}${s.length?chart(c.a,c.b,c.labels):noChart()}${legend([['순매출','#477f79'],['비용','#a15d58']])}</section><section class="dash-panel">${heading('음식과 술의 판매 구성','작은 접시와 한 잔의 판매를 나누어 봅니다','메뉴 보기','menus')}<div class="category-empty">${groups.map((g,i)=>{let rows=s.filter(r=>{let m=db.menus.find(m=>m.menu_id===r.menu_id);return g==='음식'?!isBeverage(m):m?.category===g});return `<div class="category-block"><span>${g}</span><strong>${s.length?won(sum(rows,'net_sales')):'—'}</strong><small>${s.length?'실제 기록 · 원':'판매 기록 없음'}</small></div>`}).join('')}</div><div class="scope-banner">음식은 접시, 술은 잔·병·도쿠리 등 판매 단위를 구분해 기록합니다. 서로 다른 단위의 수량을 합산하지 않습니다.</div></section></div><div class="signature-head"><h3>평소의 시그니처 소요리</h3><span>사용자 제공 메뉴 구상 · 가격과 원가 미정</span></div><div class="signature-grid">${signature.map((m,i)=>`<article class="signature-card"><div class="signature-number">0${i+1}</div><span class="pill ${i===1?'pending':''}">${esc(m.course)}</span><h3>${esc(m.name)}</h3><p>${esc(m.description)}</p><div class="signature-ingredients"><strong>메뉴 구상의 재료 연결</strong>${esc(m.ingredient_note)}</div></article>`).join('')}</div><div class="dash-row"><section class="dash-panel">${heading('계절 메뉴와 저장 재료의 연결','제철 식재료를 여러 작은 요리에 활용하는 방향','구상 메뉴','menus')}<div class="storage-pair"><div class="storage-box"><h4>장아찌 · 절임물</h4><p>광어 미소 무침 · 장아찌 두부 · 닭목살 피망</p></div><div class="storage-box"><h4>생강청 · 제철 조미료</h4><p>닭목살 양념과 저장 조미료 활용 아이디어</p></div></div><div class="storage-note">재료 연결은 메뉴 개발 구상입니다. 사용량·보관기한·실제 재고는 아직 등록되지 않았습니다.</div></section><section class="dash-panel">${heading('운영 기록 준비','수익성과 재료 잔량을 확인하기 위한 기초 기록','','')}<div class="side-row"><span>메뉴 구상</span><strong>${db.menus.length}종 <small>시그니처·후보·아이디어 포함</small></strong></div><div class="side-row"><span>재료 · 레시피</span><span class="pill pending">${db.recipes.length?'일부 등록':'등록 필요'}</span></div><div class="side-row"><span>원가 · 예상 손익 · 발주 기준</span><span class="pill pending">결정 대기</span></div></section></div>${workflow()}`};
menus=function(){const rows=db.menus.filter(m=>catalogCategory==='전체'||m.category===catalogCategory||m.tags?.includes(catalogCategory));return `${intro('평소의 메뉴와 수익성','시그니처와 개발 중인 메뉴를 구분하고, 실제 판매 기록에 연결합니다.','MENU · FOOD & DRINKS')}<div class="catalog-controls"><div class="tabs">${categoryNames.map(c=>`<button data-category="${c}" class="${catalogCategory===c?'active':''}">${c}</button>`).join('')}</div><span class="menu-count">${rows.length}종 · 중복 메뉴는 통합</span></div>${periodUI()}<div class="table-wrap"><table class="catalog-table"><thead><tr><th>메뉴</th><th>분류 · 개발 상태</th><th>판매 기준가</th><th>순매출 · 실제 기록</th><th>수익성</th></tr></thead><tbody>${rows.map(m=>{let sales=selected('sales').filter(s=>s.menu_id===m.menu_id);return `<tr><td><strong>${esc(m.name)}</strong>${m.description?`<small>${esc(m.description)}</small>`:''}</td><td><div class="tag-row">${(m.tags||[m.category]).map(t=>`<span class="pill ${t==='주류'?'drink-pill':''}">${esc(t)}</span>`).join('')}</div><small>${esc(m.status||'상태 미등록')}</small></td><td>${m.price==null?'<span class="muted">미정</span>':won(m.price)}</td><td>${sales.length?won(sum(sales,'net_sales')):'<span class="muted">기록 없음</span>'}</td><td><span class="pill pending">원가 · 기준 필요</span></td></tr>`}).join('')}</tbody></table></div><p class="compact-note">‘후보’와 ‘아이디어’는 판매 확정 메뉴가 아닙니다. 가격·원가·레시피는 임의로 채우지 않았습니다.</p>${workflow()}`};
profit=function(){let a=selected('sales'),b=selected('expenses'),c=monthly();return `${intro('실적과 손익을 확인합니다.','실제 판매·비용 기록과 아직 정해지지 않은 예상값을 구분합니다.','PERFORMANCE · ACTUAL & FORECAST')}${periodUI()}<div class="stat-grid"><div class="stat"><span class="pill">실제 기록</span><p>순매출</p><strong>${a.length?won(sum(a,'net_sales')):'—'}</strong><small>${a.length?'판매 기록 기준':'판매 기록 미등록'}</small></div><div class="stat"><span class="pill">실제 기록</span><p>운영 비용</p><strong>${b.length?won(sum(b,'amount')):'—'}</strong><small>${b.length?'일자별 비용 기록 기준':'비용 기록 미등록'}</small></div><div class="stat"><span class="pill pending">예상값 · 결정 대기</span><p>예상 손익</p><strong>기준 설정 필요</strong><small>실제 실적과 분리해 표시합니다.</small></div></div><div class="dash-row"><section class="dash-panel">${heading('기간별 매출과 비용','미등록 날짜는 확정 매출 0으로 보지 않습니다','','')}${a.length?chart(c.a,c.b,c.labels):noChart()}</section><section class="dash-panel"><h3>수익성 확인에 필요한 기준</h3><p class="muted">음식 원가, 주류 원가, 결제수수료, 공통 운영비의 포함 범위를 정해야 합니다.</p>${notice('가격·레시피·원가 기록과 손익 기준이 아직 없습니다. 최종 손익과 예상 손익은 결정 후 제공됩니다.',true)}<button data-page="expenses">비용 기록 입력 →</button></section></div>${workflow()}`};
inventory=function(){return `${intro('식재료와 저장음식을 살펴봅니다.','입고·폐기·실측 재고를 구분하고, 공통 재료의 활용을 확인합니다.','INGREDIENTS · PRESERVES','<button class="primary" data-add="inventory_events">＋ 재고 기록</button>')}${periodUI()}${db.materials.length?table(['재료','단위','계산상 잔량','발주 기준'],db.materials.map(m=>[esc(m.name),esc(m.unit),balances()[m.material_id]==null?'미등록':fmt(balances()[m.material_id])+' '+esc(m.unit),'<span class="pill pending">설정 필요</span>'])):'<div class="page-empty"><h3>평소의 재료 목록과 초기 재고가 필요합니다.</h3><p>카페의 원두·우유 재고를 평소의 실제 재고로 사용하지 않습니다.</p><span class="pill pending">재료 · 구매단위 · 레시피 · 초기 재고 등록 필요</span></div>'}<div class="signature-head"><h3>저장 식재료 활용 방향</h3><span>메뉴 개발 구상 · 재고 수치 없음</span></div><div class="planned-stock"><section class="panel"><span class="pill">장아찌 건더기</span><p>장아찌 두부 · 장아찌 무침 · 오늘의 장아찌 접시</p></section><section class="panel"><span class="pill pending">절임물 · 청</span><p>광어 소스 · 닭목살 양념 · 드레싱과 국물 조미료</p></section><section class="panel"><span class="pill drink-pill">제철 재료</span><p>차가운 해산물 → 채소·저장음식 → 구이 → 국물·식사</p></section></div>${notice('공통 재료를 여러 메뉴에 연결하는 방향은 반영했습니다. 실제 사용량, 저장음식 재고의 반영 방식과 발주 기준은 결정 대기입니다.')}<button data-page="inventory_events">입고 · 폐기 · 실사 기록 보기 →</button>`};
const oldBase=base;
base=function(){if(baseTab==='menus')return `${menus()}<div class="empty-recipes"><p>기초 자료는 읽기 전용입니다. 입력한 메뉴 구상을 그대로 보존합니다.</p><button data-base="materials">재료 · 레시피 자료 보기 →</button></div>`;return `${intro('기초 자료','평소의 메뉴 외 운영 기초 자료는 등록 대기입니다.','MASTER DATA') }<div class="tabs">${[['menus','메뉴'],['materials','재료'],['recipes','레시피'],['price_history','가격 이력'],['suppliers','공급사'],['calendar','영업 달력'],['monthly_expense_plan','월 비용 계획']].map(([k,l])=>`<button data-base="${k}" class="${baseTab===k?'active':''}">${l}</button>`).join('')}</div>${db[baseTab]?.length?oldBase():'<div class="page-empty"><h3>아직 등록된 기초 자료가 없습니다.</h3><p>평소의 실제 운영 자료를 확인한 뒤 등록해야 합니다.</p></div>'}`};
recordPage=function(key){let rows=selected(key).filter(r=>(!channel||r.channel===channel)&&(!query||JSON.stringify(r).includes(query)||menuName(r.menu_id||'').includes(query)||materialName(r.material_id||'').includes(query)));let list=rows.slice(offset,offset+20),cols=key==='sales'?['date','menu_id','channel','quantity','net_sales','payment_fee']:key==='expenses'?['date','category','amount','recognition']:['date','material_id','event_type','quantity','unit','counted_quantity'];return `${intro(`${names[key]} 기록`,key==='sales'?'음식·주류를 메뉴별로 기록하고 접시·잔·병 등의 판매 단위를 구분합니다.':'평소의 실제 운영 기록을 보관합니다.','OPERATING RECORDS')}${periodUI()}<div class="toolbar"><div class="filters"><input id="search" value="${esc(query)}" placeholder="메뉴명 · 항목 · ID 검색" aria-label="기록 검색">${key==='sales'?`<select id="channel" aria-label="판매 채널"><option value="">전체 채널</option>${['매장','포장'].map(c=>`<option ${channel===c?'selected':''}>${c}</option>`).join('')}</select>`:''}<span class="muted">${rows.length} 건</span></div><div class="actions">${key!=='inventory_events'?`<button data-template="${key}">↓ 엑셀 양식</button><button data-import="${key}">↑ 엑셀 가져오기</button>`:''}<button class="primary" data-add="${key}">＋ ${names[key]} 기록 입력</button></div></div>${key==='expenses'?notice('월 비용 계획과 실제 비용 기록을 이중 합산하지 않습니다.'):key==='inventory_events'?notice('입고는 양수, 폐기는 음수로 기록합니다. 실사는 실측 수량을 별도로 보관합니다.'):''}<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${c==='quantity'&&key==='sales'?'판매 수량 · 단위':fields[key].find(f=>f[0]===c)?.[1]||c}</th>`).join('')}<th>관리</th></tr></thead><tbody>${list.map(r=>`<tr>${cols.map(c=>`<td>${c==='menu_id'?esc(menuName(r[c])):c==='material_id'?esc(materialName(r[c])):c==='quantity'&&key==='sales'?fmt(r[c])+' '+esc(r.quantity_unit):r[c]==null?'—':typeof r[c]==='number'?fmt(r[c]):esc(r[c])}</td>`).join('')}<td><button data-edit="${key}|${r[fields[key][0][0]]}">수정</button><button class="danger" data-delete="${key}|${r[fields[key][0][0]]}">삭제</button></td></tr>`).join('')||`<tr><td colspan="${cols.length+1}" class="empty">조회 기간에 등록된 ${names[key]} 기록이 없습니다.</td></tr>`}</tbody></table></div><div class="pager"><button id="prev" ${offset===0?'disabled':''}>이전</button><span>${rows.length?Math.floor(offset/20)+1:0} / ${Math.ceil(rows.length/20)}</span><button id="next" ${offset+20>=rows.length?'disabled':''}>다음</button></div>`};
opts=function(type){if(type==='category')return [...new Set([...expenseCategories,...db.expenses.map(r=>r.category)])].map(x=>[x,x]);if(type==='salesUnit')return [['','단위 선택'],...['접시','잔','병','도쿠리','인분','개'].map(x=>[x,x])];if(type==='menu')return db.menus.map(m=>[m.menu_id,`${m.name} · ${m.category} (${m.status||'기록 메뉴'})`]);return oldOpts(type)};
recordModal=function(key,id=null,preview=false,error=false){if(key==='inventory_events'&&!db.materials.length){showModal('재고 기록 준비',notice('평소의 재료와 기준단위가 아직 등록되지 않았습니다. 재료 목록·초기 재고를 먼저 확인해야 재고 기록을 연결할 수 있습니다.'),'<button data-close>확인</button>');return}oldRecordModal(key,id,preview,error);if(key==='sales'){const form=$('#recordForm');if(!id){form.elements.recipe_version.value='미등록';form.elements.recipe_version.readOnly=true}form.insertAdjacentHTML('afterbegin','<p class="form-hint">메뉴 목록에는 후보와 아이디어도 포함됩니다. 실제로 판매한 메뉴만 선택하고, 가격·원가·판매 단위를 직접 입력해 주세요.</p>')}if(error)$('#formError').textContent=key==='sales'?'판매 수량과 판매 단위를 확인해 주세요.':key==='expenses'?'비용 금액을 입력해 주세요.':'재료와 수량을 확인해 주세요.'};
validate=function(key,r,id){const error=oldValidate(key,r,id);if(error)return error;if(key==='sales'&&!['접시','잔','병','도쿠리','인분','개'].includes(r.quantity_unit))return '판매 단위를 선택해 주세요.';return ''};
persist=function(){try{localStorage.setItem(STORE_KEY,JSON.stringify(db));return true}catch{toast('저장 공간이 부족합니다. 백업을 내려받아 주세요.');return false}};
validBackup=function(o){let d=o?.data;if(o?.schema!==BACKUP_SCHEMA||d?.meta?.dataset_id!=='pyeongso-operations'||!d.settings)return false;for(let k of ['sales','expenses','inventory_events','menus','materials','recipes','calendar','opening_inventory','suppliers','price_history','monthly_expense_plan'])if(!Array.isArray(d[k]))return false;for(let k of ['sales','expenses','inventory_events']){let ids=new Set();for(let r of d[k]){if(!fields[k].every(([f,l,t])=>['optional','supplier'].includes(t)||f==='reason'||r[f]!=null)||!r.date||ids.has(r[fields[k][0][0]]))return false;ids.add(r[fields[k][0][0]]);}}return true};
backup=function(){return `${intro('기록을 저장하고 보관합니다.','평소의 메뉴 구상과 운영 기록을 함께 백업합니다.','SAVE · BACKUP & RESTORE')}${notice('평소의 자료는 별도의 브라우저 저장 공간에 보관합니다. 이전 카페 자료와 섞이지 않습니다.')}<div class="panel-grid"><section class="panel"><h3>평소의 저장 기록</h3><span class="pill saved">내 브라우저에 저장</span><div class="backup-meta">${[['메뉴 구상',db.menus.length],['판매 기록',db.sales.length],['비용 기록',db.expenses.length],['재고 기록',db.inventory_events.length]].map(([l,v])=>`<div><span class="muted">${l}</span><strong>${fmt(v)} <small>${l==='메뉴 구상'?'종':'건'}</small></strong></div>`).join('')}</div><button class="primary" id="save">지금 저장</button></section><section class="panel"><h3>전체 백업</h3><p class="muted">메뉴와 기초 자료, 판매·비용·재고 기록을 보관합니다.</p><button class="primary" id="backup">↓ 평소 백업 내려받기</button><hr><h3>백업 복원</h3><p class="muted">평소용 백업 파일을 확인한 뒤 현재 자료를 교체합니다.</p><button id="restore">↑ 백업 파일 선택</button></section></div>`};
template=function(key){let wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet([fields[key].map(f=>f[1])]),names[key]+'기록');XLSX.writeFile(wb,`평소_${names[key]}기록_양식.xlsx`);toast('평소 엑셀 양식을 내려받았습니다.')};
restoreModal=function(){showModal('평소 백업 파일 선택','<div class="drop">평소 전체 기록 백업 파일을 선택해 주세요.<input id="restoreFile" type="file" accept=".json" aria-label="백업 파일 선택"></div><div id="restoreError" role="alert"></div>','<button data-close>취소</button>');$('#restoreFile').onchange=async e=>{try{let o=JSON.parse(await e.target.files[0].text());if(!validBackup(o))throw Error('평소용 백업 형식이 아니거나 기록이 손상되었습니다.');showModal('평소 백업 복원 확인',`<p>메뉴 ${fmt(o.data.menus.length)}종 · 판매 ${fmt(o.data.sales.length)}건 · 비용 ${fmt(o.data.expenses.length)}건</p>${notice('현재 평소 기록을 교체합니다. 기존 카페 자료에는 영향을 주지 않습니다.',true)}`,'<button id="beforeBackup">현재 자료 백업</button><button data-close>취소</button><button id="confirmRestore" class="primary">복원</button>');$('#beforeBackup').onclick=()=>download('평소_복원전_백업.json',JSON.stringify({schema:BACKUP_SCHEMA,data:db}),'application/json');$('#confirmRestore').onclick=()=>{let old=db;db=o.data;if(!persist()){db=old;return}closeModal();render();toast('평소 기록을 복원했습니다.')}}catch(err){$('#restoreError').innerHTML=notice(esc(err.message),true)}}};
const oldCanvas=canvas;
canvas=function(){return oldCanvas().replaceAll('운영 현황','평소의 현황').replaceAll('재료 잔량','식재료 · 저장음식').replaceAll('메뉴 수익성','메뉴 · 수익성')};
const oldStateModal=stateModal;
stateModal=function(s){if(s==='restoreConfirm'){showModal('평소 백업 복원 확인',`<p>메뉴 ${db.menus.length}종 · 판매 ${db.sales.length}건 · 비용 ${db.expenses.length}건 · 재고 ${db.inventory_events.length}건</p>${notice('화면 예시입니다. 실제 데이터는 교체하지 않습니다.',true)}`);return}oldStateModal(s)};
bind=function(){oldBind();document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{catalogCategory=b.dataset.category;render()});document.querySelectorAll('[data-preview]').forEach(el=>el.onclick=()=>{let [k,mode]=el.dataset.preview.split('|'),r=db[k][0];if((mode==='edit'||mode==='delete')&&!r){showModal(`${names[k]} 기록 ${mode==='edit'?'수정':'삭제'}`,notice('아직 실제 기록이 없습니다. 기록을 먼저 입력하면 수정·삭제할 수 있습니다.'));return}navigate(k);if(mode==='delete')deleteModal(k,r[fields[k][0][0]],true);else recordModal(k,mode==='edit'?r[fields[k][0][0]]:null,true,mode==='error')});if($('#backup'))$('#backup').onclick=()=>download('평소_전체기록_백업.json',JSON.stringify({schema:BACKUP_SCHEMA,data:db},null,2),'application/json');if($('#restore'))$('#restore').onclick=restoreModal;};
chart=function(a,b,labels){let max=Math.max(...a,...b,1),base=185,step=720/Math.max(a.length,1);return `<svg class="chart" viewBox="0 0 800 225" role="img" aria-label="기간별 실제 기록 차트">${[0,.25,.5,.75,1].map(f=>{let y=base-f*145;return `<line x1="55" y1="${y}" x2="785" y2="${y}" stroke="#e4e9df"/><text x="48" y="${y+4}" text-anchor="end" fill="#899882" font-size="10">${fmt(Math.round(max*f/1000))}천</text>`}).join('')}${a.map((v,i)=>`<rect x="${62+i*step}" y="${base-v/max*145}" width="${step*.32}" height="${v/max*145}" fill="#719990" rx="2"/><text x="${62+i*step+step*.3}" y="204" fill="#899882" text-anchor="middle" font-size="10">${esc(labels[i])}</text>`).join('')}<polyline points="${b.map((v,i)=>`${62+i*step+step*.3},${base-v/max*145}`).join(' ')}" fill="none" stroke="#a15d58" stroke-width="2.4"/></svg>`};
monthly=function(){let rows=[...selected('sales'),...selected('expenses')];let days=[...new Set(rows.map(r=>r.date))].sort(),months=[...new Set(days.map(d=>d.slice(0,7)))];let keys=months.length>1?months:days;return {labels:keys.map(k=>k.length===7?k.slice(2).replace('-','.'):k.slice(5).replace('-','.')),a:keys.map(k=>sum(selected('sales').filter(r=>r.date.startsWith(k)),'net_sales')),b:keys.map(k=>sum(selected('expenses').filter(r=>r.date.startsWith(k)),'amount'))}};
async function init(){try{let stored=localStorage.getItem(STORE_KEY);if(stored){let parsed=JSON.parse(stored);if(validBackup({schema:BACKUP_SCHEMA,data:parsed}))db=parsed}if(!db){let response=await fetch('pyeongso-data.json');if(!response.ok)throw Error('평소 자료 요청 실패');db=await response.json()}const p=location.hash.slice(1);if(pages[p]||p==='inventory_events')page=p;render()}catch(err){$('#app').innerHTML=notice('평소 자료를 불러오지 못했습니다. '+esc(err.message),true)+'<button onclick="location.reload()">다시 시도</button>'}}
init();
